SINA_SMART["viro1-vaccines-antivirals"] = {"lecture":"viro1-vaccines-antivirals","title":"Vaccines and antiviral therapy","mapStatus":"auto: generated by universal.py from the lecture summary and key points; not human-reviewed","los":[{"id":"viro1-vaccines-antivirals:e0","text":"Jenner (1796) used cowpox: origin of 'vaccine'.","topic":"What a vaccine is","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"viro1-vaccines-antivirals:e1","text":"Vaccines induce neutralising antibodies, cytotoxic T cells and memory.","topic":"What a vaccine is","sec":0,"importance":"core","highYield":"insufficient-source"},{"id":"viro1-vaccines-antivirals:e2","text":"Live attenuated: MMR, varicella, yellow fever, oral polio, rotavirus; not in pregnancy or immunodeficiency.","topic":"Types of viral vaccine","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"viro1-vaccines-antivirals:e3","text":"Inactivated: rabies, injectable polio, HAV. Recombinant: HBV. VLP: HPV. mRNA/vector: SARS-CoV-2.","topic":"Types of viral vaccine","sec":1,"importance":"core","highYield":"insufficient-source"},{"id":"viro1-vaccines-antivirals:e4","text":"Passive immunisation: immediate, temporary (~4 months).","topic":"Memory, herd immunity, passive immunisation","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"viro1-vaccines-antivirals:e5","text":"Herd immunity protects the unvaccinated.","topic":"Memory, herd immunity, passive immunisation","sec":2,"importance":"core","highYield":"insufficient-source"},{"id":"viro1-vaccines-antivirals:e6","text":"Antivirals are hard to make selective because viruses use host machinery.","topic":"Antivirals: why so few","sec":3,"importance":"core","highYield":"insufficient-source"},{"id":"viro1-vaccines-antivirals:e7","text":"Aciclovir (1983) and AZT (1990) were landmarks; DAAs cure HCV.","topic":"Antivirals: why so few","sec":3,"importance":"core","highYield":"insufficient-source"},{"id":"viro1-vaccines-antivirals:e8","text":"Targets: entry, genome synthesis, protein processing, assembly, release.","topic":"Targets","sec":4,"importance":"core","highYield":"insufficient-source"}],"vmap":{},"mlevel":{"hd3hrl":"a","175a75l":"a","fu4fmv":"a","t3yd6a":"a","33t3":"a","p21sol":"a","10f1a8f":"a","pkc8ez":"a","18j99a1":"a","1nf2erq":"a","1a1dryc":"a","1lrx66y":"a","1vy9sb2":"a","1l9uho9":"x"},"mapCounts":{"verified":0,"auto":13,"ambiguous":0,"missing":1},"mrules":[],"items":[],"experimental":[],"status":{},"difficulty":{},"expl":{"viro1-vaccines-antivirals:e0":{"s":0,"u":["Jenner (1796) used cowpox: origin of 'vaccine'.","'Vaccine' comes from Latin vaccinus (of cows), after Jenner (1796) used cowpox from the hand of the milkmaid Sarah Nelms to protect against smallpox."],"dp":[]},"viro1-vaccines-antivirals:e1":{"s":0,"u":["Vaccines induce neutralising antibodies, cytotoxic T cells and memory.","Viral epitopes induce both B-cell and T-cell immunity (neutralising antibodies and cytotoxic T cells), and memory can last years or a lifetime."],"dp":[]},"viro1-vaccines-antivirals:e2":{"s":1,"u":["Live attenuated: MMR, varicella, yellow fever, oral polio, rotavirus; not in pregnancy or immunodeficiency.","Live attenuated (no longer pathogenic but immunogenic): yellow fever, oral polio, measles, mumps, rubella, varicella, rotavirus.","Strong, long-lasting immunity but contraindicated in pregnancy and immunodeficiency ."],"dp":[]},"viro1-vaccines-antivirals:e3":{"s":1,"u":["Inactivated: rabies, injectable polio, HAV. Recombinant: HBV. VLP: HPV. mRNA/vector: SARS-CoV-2.","Inactivated whole virus : rabies, injectable (formalin-killed) polio, HAV.","Viral vector (adenovirus) and nucleic acid (mRNA) vaccines, as for SARS-CoV-2: the cell makes the antigen (spike) itself."],"dp":[]},"viro1-vaccines-antivirals:e4":{"s":2,"u":["Passive immunisation: immediate, temporary (~4 months).","Passive immunisation with human immunoglobulin gives immediate but temporary protection (about 4 months) after exposure to hepatitis A and B, measles, varicella, rabies; it can be given with inactivated vaccines (rabies, HBV)."],"dp":[]},"viro1-vaccines-antivirals:e5":{"s":2,"u":["Herd immunity protects the unvaccinated.","Herd immunity : when enough of the population is immune, transmission stops and the unvaccinated are protected too."],"dp":[]},"viro1-vaccines-antivirals:e6":{"s":3,"u":["Antivirals are hard to make selective because viruses use host machinery.","Viruses use the host cell's own machinery, so drugs that block them risk harming the cell: selectivity is difficult and toxicity a problem, unlike antibiotics that hit bacterial structures."],"dp":[]},"viro1-vaccines-antivirals:e7":{"s":3,"u":["Aciclovir (1983) and AZT (1990) were landmarks; DAAs cure HCV.","Landmarks: idoxuridine and vidarabine (1962, toxic, limited); aciclovir (1983), proof that safe, highly effective antivirals are possible; interferon-α (1980s); zidovudine (AZT) (1990), the first useful HIV reverse transcriptase inhibitor; protease inhibitors and HAART (mid-1990s); lamivudine for HBV and neuraminidase inhibitors for influenza (early 2000s); direct-acting antivirals for HCV (from 2011).","HCV cure shows what combination therapy can achieve."],"dp":[]},"viro1-vaccines-antivirals:e8":{"s":4,"u":["Targets: entry, genome synthesis, protein processing, assembly, release.","Antivirals act at (1) entry (attachment, fusion), (2) nucleic acid synthesis (nucleoside analogues such as aciclovir, reverse transcriptase inhibitors, polymerase inhibitors), (3) late protein synthesis and processing (protease inhibitors), (4) assembly and (5) release (neuraminidase inhibitors)."],"dp":[]}},"meta":{"hd3hrl":{"a":"recall","vg":"viro1-vaccines-antivirals:e0/recall/1"},"175a75l":{"a":"recall","vg":"viro1-vaccines-antivirals:e2/recall/1"},"fu4fmv":{"a":"recall","vg":"viro1-vaccines-antivirals:e2/recall/2"},"t3yd6a":{"a":"recall","vg":"viro1-vaccines-antivirals:e8/recall/1"},"33t3":{"a":"recall","vg":"viro1-vaccines-antivirals:e4/recall/1"},"p21sol":{"a":"recall","vg":"viro1-vaccines-antivirals:e5/recall/1"},"10f1a8f":{"a":"relationship","vg":"viro1-vaccines-antivirals:e6/relationship/1"},"pkc8ez":{"a":"recall","vg":"viro1-vaccines-antivirals:e7/recall/1"},"18j99a1":{"a":"recall","vg":"viro1-vaccines-antivirals:e7/recall/2"},"1nf2erq":{"a":"recall","vg":"viro1-vaccines-antivirals:e8/recall/2"},"1a1dryc":{"a":"recall","vg":"viro1-vaccines-antivirals:e0/recall/2"},"1lrx66y":{"a":"recall","vg":"viro1-vaccines-antivirals:e3/recall/1"},"1vy9sb2":{"a":"recall","vg":"viro1-vaccines-antivirals:e0/recall/3"}},"explRev":"e6ab5e67c046"};
